var o=[{title:`Rodzaje mocowań`,text:`Drążki z dźwignią we framudze drzwi, rozprężne drążki napinane, stałe drążki ścienne i drążki sufitowe montuje się na różne sposoby. Drążek sprzedawany jako „kompatybilny z drzwiami” nie pasuje do każdej listwy, ściany czy ościeżnicy. Niektóre typy wymagają mocowań konstrukcyjnych w solidnych podporach, a inne zależą od określonego kształtu ościeżnicy.`},{title:`Sprawdź nośność i konstrukcję`,text:`Przeczytaj instrukcję producenta i limit obciążenia, w tym informację, czy dozwolone są ruchy dynamiczne. Weź pod uwagę całą masę ciała plus dodatkową siłę bujania lub ciągnięcia. Sprawdź śruby, wsporniki, wyściełanie i powierzchnie, których drążek dotyka lub przy których się znajduje. Jeśli nie jesteś pewien konstrukcji budynku lub sposobu montażu, zapytaj wykwalifikowanego montera.`},{title:`Testuj krok po kroku`,text:`Przed pełnym zwisem upewnij się, że drążek jest prawidłowo osadzony i nie może się obracać, przesuwać ani przemieszczać. Trzymaj stopy na podłodze i naciskaj na niego delikatnie i z kontrolą. Przejdź do częściowego zwisu, a potem pełnego zwisu z podparciem dopiero wtedy, gdy wiesz, że montaż jest solidny. Krótki test nie może dowieść, że uszkodzone elementy lub nieodpowiednia ościeżnica są bezpieczne.`},{title:`Częste zagrożenia`,text:`Nie mocuj gum ani nie wykonuj podciągania kipping, bujanego lub z obciążeniem, chyba że produkt jest zaprojektowany i zamontowany dokładnie do tego. Zostaw miejsce na głowę, łokcie i stopy, bez szkła i ostrych mebli w pobliżu. Przestań używać drążka, który skrzypi, ślizga się, wygina lub luzuje.`},{title:`Korzystanie z TrainUp`,text:`W Profilu oznacz swój drążek do podciągania jako bezpiecznie zamontowany dopiero po sprawdzeniu wszystkiego powyższego. Do tego czasu plan pomija ćwiczenia wymagające drążka, a wiosłowanie lub ćwiczenia z gumą na bezpiecznym zaczepie trenują to samo ciągnięcie. Jeśli jesteś początkujący, dobrymi pierwszymi krokami, gdy drążek jest bezpieczny, są zwisy z podparciem, ciągnięcia łopatkowe lub podciąganie z pomocą.`}];var a=[{label:`Mayo Clinic: bezpieczeństwo i technika treningu z obciążeniem`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Biblioteka ćwiczeń ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:o,sources:a};export{n as default,o as sections,a as sources};